def compute(vars):
    old = vars["v1"]
    new = vars["v2"]

    if old == 0:
        return {
            "value": None,
            "trace": {
                "old_value": old,
                "new_value": new,
                "output_meta": {
                    "currency": None,
                    "scale": None,
                    "unit": "percentage"
                }
            }
        }

    change_ratio = (new - old) / old
    percentage_change = change_ratio * 100

    return {
        "value": percentage_change,
        "trace": {
            "old_value": old,
            "new_value": new,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
